// Source-specific extraction and transformation live HERE and nowhere else.
// Scope §88: source field names must not leak past this boundary -- everything
// downstream sees only canonical objects.
//
// Jobs reference contacts and users by SOURCE id. BuilderLync resolves those to destination ids from migration_object_map, so this workflow must not attempt to resolve them itself (Scope §69).
//
// Replace the body of extractPage() with the vendor call for this source. The
// rest of this workflow is source-agnostic and is shared by every connector.

const input = $('Load Checkpoint').first().json;
const plan = $('Workflow Input').first().json;

async function extractPage(cursor, pageSize) {
  // --- VENDOR CALL GOES HERE ---------------------------------------------
  // Must return { records: [...], cursor: <opaque>, hasMore: boolean }.
  // Scope §26: the adapter decides the pagination shape (page / offset /
  // cursor / next-URL / date-range); this workflow only passes the cursor
  // back and forth opaquely.
  throw new Error(
    'MIG-140 has no vendor extraction wired up yet. Implement extractPage() ' +
    'for the source connector, or run the migration through the in-process ' +
    'orchestrator (POST /api/migrations/:id/start), which uses the same adapter contract.'
  );
}

const page = await extractPage(input.cursor, plan.batch_size);

// Canonical shape (Guide §3.1): every record carries its own provenance so any
// BuilderLync row can be traced back to source platform, tenant, type and id.
const records = page.records.map((raw) => ({
  source_id: String(raw.id),
  idempotency_key: `mig_${plan.migration_id}:${plan.source_platform}:job:${raw.id}`,
  content_hash: null, // computed by the Hash Records node below
  payload: {
    migration_id: plan.migration_id,
    source_platform: plan.source_platform,
    source_object_type: 'job',
    source_object_id: String(raw.id),
    transformer_version: `${plan.source_platform}-job-v1.0.0`,
    warnings: [],
    // ... map the vendor's fields onto the canonical schema here ...
  },
}));

return [{
  json: {
    ...plan,
    records,
    cursor: page.cursor,
    has_more: page.hasMore,
    batch_number: (input.batch_number ?? 0) + 1,
    records_processed: (input.records_processed ?? 0) + records.length,
  },
}];

// Scope §11: the content hash is what lets a replay skip an unchanged record
// instead of issuing a pointless destination write. It must be computed the
// same way on every run, so object keys are sorted before hashing.
const crypto = require('crypto');

function stable(value) {
  if (value === null || value === undefined) return 'null';
  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
  if (typeof value === 'object') {
    return `{${Object.entries(value)
      .filter(([k]) => !['migration_id', 'transformer_version', 'warnings', 'raw_source_reference'].includes(k))
      .sort(([a], [b]) => (a < b ? -1 : 1))
      .map(([k, v]) => `${JSON.stringify(k)}:${stable(v)}`)
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

const item = $input.first().json;
item.records = item.records.map((r) => ({
  ...r,
  content_hash: crypto.createHash('sha256').update(stable(r.payload)).digest('hex'),
}));
return [{ json: item }];

// Scope §44: the response must carry a result for EVERY record sent. Verifying
// it here means a short response surfaces immediately, rather than as an
// unexplained reconciliation variance hours later.
const sent = $('Hash Records').first().json.records;
const response = $input.first().json;
const results = response.results ?? [];

const returned = new Set(results.map((r) => r.source_id));
const missing = sent.filter((r) => !returned.has(r.source_id));

if (missing.length > 0) {
  throw new Error(
    `Ingestion returned ${results.length} results for ${sent.length} records; ` +
    `${missing.length} unaccounted for (first: ${missing[0].source_id}).`
  );
}

const tally = results.reduce((acc, r) => {
  acc[r.status] = (acc[r.status] ?? 0) + 1;
  return acc;
}, {});

return [{ json: { ...$('Hash Records').first().json, results, tally } }];
